"""
File-based discovery for the Agents service.

Discovers AI coding tool sessions by scanning transcript/session files
on disk (Claude, OpenCode, Codex). Sessions with recent file activity
are marked active; stale sessions are marked stopped.

Hooks remain the source of truth for registering sessions (they provide
session_id + PID via the CLI register command). Discovery supplements
this by scanning for sessions that may not have been registered via hooks.
"""

import json
import logging
import subprocess
import time
from pathlib import Path
from typing import TYPE_CHECKING, Any, Optional

from .schemas import AgentSession, AgentStatus, AgentTask, AgentTool, GitInfo

if TYPE_CHECKING:
    from .schemas import TranscriptEntry

logger = logging.getLogger(__name__)

# Sessions with file activity older than this are considered stopped.
ACTIVITY_THRESHOLD_S = 1800  # 30 minutes

# Sessions newer than this get full detail enrichment during discovery.
# Older sessions get lightweight extraction (path-based only) for speed.
ENRICHMENT_THRESHOLD_S = 30 * 24 * 3600  # 30 days


# ===========================================================================
# Shared utilities
# ===========================================================================


def _cwd_to_project_slug(cwd: str) -> str:
    """Convert a cwd path to Claude's project directory slug format."""
    return cwd.replace("/", "-").replace("_", "-")


def _get_git_info(cwd: Optional[str]) -> dict[str, Any]:
    """Extract git metadata from a working directory.

    Returns dict with: git_branch, git_worktree, github_repo.
    """
    info: dict[str, Any] = {}
    if not cwd or not Path(cwd).exists():
        return info

    try:
        result = subprocess.run(
            ["git", "rev-parse", "--is-inside-work-tree"],
            capture_output=True,
            text=True,
            timeout=3,
            cwd=cwd,
            check=False,
        )
        if result.returncode != 0:
            return info

        result = subprocess.run(
            ["git", "rev-parse", "--abbrev-ref", "HEAD"],
            capture_output=True,
            text=True,
            timeout=3,
            cwd=cwd,
            check=False,
        )
        branch = result.stdout.strip()
        if branch:
            info["git_branch"] = branch

        git_path = Path(cwd) / ".git"
        info["git_worktree"] = git_path.is_file()

        result = subprocess.run(
            ["git", "config", "--get", "remote.origin.url"],
            capture_output=True,
            text=True,
            timeout=3,
            cwd=cwd,
            check=False,
        )
        remote = result.stdout.strip()
        if remote:
            if remote.startswith("git@github.com:"):
                remote = "https://github.com/" + remote[15:]
            if remote.endswith(".git"):
                remote = remote[:-4]
            if "github.com" in remote:
                info["github_repo"] = remote
    except Exception as e:
        logger.debug("Error getting git info for %s: %s", cwd, e)

    return info


def _get_mcp_servers_for_tool(tool_id: str, port: int = 0) -> list[str]:
    """Get configured MCP server names for an agent."""
    import urllib.error
    import urllib.request

    servers: list[str] = []
    try:
        if tool_id == "claude":
            settings_path = Path.home() / ".claude" / "settings.json"
            if settings_path.exists():
                with open(settings_path, "r", encoding="utf-8") as f:
                    settings = json.load(f)
                    mcp = settings.get("mcpServers", {})
                    servers = list(mcp.keys())
        elif tool_id == "codeq" and port:
            url = f"http://127.0.0.1:{port}/mcp"
            req = urllib.request.Request(url, method="GET")
            req.add_header("Accept", "application/json")
            with urllib.request.urlopen(req, timeout=2) as resp:
                if resp.status == 200:
                    data = json.loads(resp.read().decode("utf-8"))
                    if isinstance(data, dict):
                        servers = list(data.keys())
    except Exception as e:
        logger.debug("Error getting MCP servers for %s: %s", tool_id, e)
    return servers


def _tail_read_jsonl(filepath: Path, n_lines: int = 10) -> dict[str, Any]:
    """Read last N lines of a JSONL file and extract useful info."""
    info: dict[str, Any] = {}
    try:
        with open(filepath, "rb") as f:
            f.seek(0, 2)
            file_size = f.tell()
            if file_size == 0:
                return info
            chunk_size = min(file_size, 8192 * n_lines)
            f.seek(file_size - chunk_size)
            data = f.read().decode("utf-8", errors="replace")

        lines = [l for l in data.strip().split("\n") if l.strip()]
        recent_lines = lines[-n_lines:]

        for line in reversed(recent_lines):
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                continue
            # Model can be at top level or nested under message
            model = entry.get("model") or (entry.get("message") or {}).get("model")
            if not info.get("model") and model:
                info["model"] = model
            if not info.get("cost_usd") and entry.get("costUSD"):
                info["cost_usd"] = entry["costUSD"]
            if not info.get("session_id") and entry.get("sessionId"):
                info["session_id"] = entry["sessionId"]
            if not info.get("cwd") and entry.get("cwd"):
                info["cwd"] = entry["cwd"]
    except Exception as e:
        logger.debug("Error tail-reading JSONL %s: %s", filepath, e)
    return info


def _get_claude_tasks(session_id: Optional[str]) -> list[dict[str, Any]]:
    """Read Claude Code task list for a session."""
    if not session_id:
        return []

    tasks_dir = Path.home() / ".claude" / "tasks" / session_id
    if not tasks_dir.exists():
        return []

    tasks = []
    try:
        for task_file in sorted(tasks_dir.glob("*.json")):
            try:
                with open(task_file, "r", encoding="utf-8") as f:
                    task = json.load(f)
                    tasks.append(
                        {
                            "id": task.get("id", ""),
                            "subject": task.get("subject", ""),
                            "status": task.get("status", "pending"),
                            "activeForm": task.get("activeForm", ""),
                        }
                    )
            except (json.JSONDecodeError, OSError):
                continue
    except Exception as e:
        logger.debug("Error reading Claude tasks for %s: %s", session_id, e)

    return tasks


# ===========================================================================
# Status detection
# ===========================================================================


def _detect_claude_status_from_transcript(
    transcript_path: Optional[str],
) -> AgentStatus:
    """Detect Claude session status from transcript file."""
    if not transcript_path:
        return AgentStatus.IDLE

    path = Path(transcript_path)
    if not path.exists():
        return AgentStatus.IDLE

    try:
        mtime = path.stat().st_mtime
        age = time.time() - mtime

        if age > 30:
            return AgentStatus.IDLE

        with open(path, "rb") as f:
            f.seek(0, 2)
            file_size = f.tell()
            if file_size == 0:
                return AgentStatus.IDLE
            chunk_size = min(file_size, 4096)
            f.seek(file_size - chunk_size)
            data = f.read().decode("utf-8", errors="replace")

        lines = [l for l in data.strip().split("\n") if l.strip()]
        if lines:
            try:
                last_entry = json.loads(lines[-1])
                entry_type = last_entry.get("type", "")
                role = last_entry.get("role", "")

                if entry_type == "assistant" or role == "assistant":
                    return AgentStatus.WORKING
                if entry_type == "user" or role == "user":
                    return AgentStatus.WORKING
            except json.JSONDecodeError:
                pass

        return AgentStatus.WORKING if age < 5 else AgentStatus.IDLE

    except Exception as e:
        logger.debug("Error detecting Claude status from transcript: %s", e)
        return AgentStatus.IDLE


def _detect_codex_status_from_rollout(
    transcript_path: Optional[str],
) -> AgentStatus:
    """Detect Codex session status from the rollout JSONL file."""
    if not transcript_path:
        return AgentStatus.IDLE

    path = Path(transcript_path)
    if not path.exists():
        return AgentStatus.IDLE

    try:
        mtime = path.stat().st_mtime
        age = time.time() - mtime

        if age > 30:
            return AgentStatus.IDLE

        with open(path, "rb") as f:
            f.seek(0, 2)
            file_size = f.tell()
            if file_size == 0:
                return AgentStatus.IDLE
            chunk_size = min(file_size, 4096)
            f.seek(file_size - chunk_size)
            data = f.read().decode("utf-8", errors="replace")

        lines = [l for l in data.strip().split("\n") if l.strip()]
        for line in reversed(lines):
            try:
                entry = json.loads(line)
                entry_type = entry.get("type", "")
                if entry_type == "event_msg":
                    evt = entry.get("payload", {}).get("type", "")
                    if evt == "task_complete":
                        return AgentStatus.IDLE
                    if evt in (
                        "task_started",
                        "agent_message",
                        "agent_reasoning",
                        "exec_command",
                        "tool_call",
                    ):
                        return AgentStatus.WORKING
                    if evt == "user_message":
                        return AgentStatus.WAITING
            except json.JSONDecodeError:
                continue

        return AgentStatus.WORKING if age < 5 else AgentStatus.IDLE

    except Exception as e:
        logger.debug("Error detecting Codex status from %s: %s", transcript_path, e)
        return AgentStatus.IDLE


def detect_agent_status(tool_id: str, details: Optional[dict] = None) -> AgentStatus:
    """Detect the status of an AI agent session from file-based signals.

    Args:
        tool_id: The tool identifier ("claude", "codeq", "codex").
        details: Pre-fetched detail dict (transcript_path, api status, etc.).

    Returns:
        AgentStatus enum value.
    """
    if tool_id == "claude":
        transcript_path = (details or {}).get("transcript_path")
        return _detect_claude_status_from_transcript(transcript_path)

    if tool_id == "codeq":
        if details and details.get("api_available"):
            status = details.get("status", "unknown")
            if status == "busy":
                return AgentStatus.WORKING
            if status == "retry":
                return AgentStatus.WAITING
            if status == "idle":
                return AgentStatus.IDLE
            return AgentStatus.IDLE
        return AgentStatus.IDLE

    if tool_id == "codex":
        return _detect_codex_status_from_rollout((details or {}).get("transcript_path"))

    return AgentStatus.IDLE


# ===========================================================================
# Detail enrichment (file-based, no PID needed)
# ===========================================================================


def _get_claude_session_title(project_dir: Path, session_id: str) -> Optional[str]:
    """Read customTitle from sessions-index.json if available."""
    index_path = project_dir / "sessions-index.json"
    if not index_path.exists():
        return None
    try:
        data = json.loads(index_path.read_text())
        for entry in data.get("entries", []):
            if entry.get("sessionId") == session_id:
                return entry.get("customTitle") or entry.get("summary") or None
    except Exception:
        pass
    return None


def get_claude_details_from_transcript(
    transcript_path: Path,
) -> dict[str, Any]:
    """Extract Claude Code session info from a transcript file.

    Instead of finding the transcript via PID/cwd, starts from a known
    transcript path and extracts all available details.
    """
    details: dict[str, Any] = {}
    details["transcript_path"] = str(transcript_path)
    details["session_id"] = transcript_path.stem

    # Read session title from sessions-index.json
    title = _get_claude_session_title(transcript_path.parent, transcript_path.stem)
    if title:
        details["terminal_name"] = title

    home = Path.home()
    claude_dir = home / ".claude"

    # Read stats cache for aggregate usage
    stats_path = claude_dir / "stats-cache.json"
    if stats_path.exists():
        try:
            with open(stats_path, "r", encoding="utf-8") as f:
                stats = json.load(f)
                if "totalCost" in stats:
                    details["total_cost"] = stats["totalCost"]
                if "totalTokens" in stats:
                    details["total_tokens"] = stats["totalTokens"]
        except Exception as e:
            logger.debug("Error reading Claude stats cache: %s", e)

    # Extract info from transcript content
    session_info = _tail_read_jsonl(transcript_path, n_lines=10)
    if session_info:
        # Prefer session_id from transcript content if available
        if session_info.get("session_id"):
            details["session_id"] = session_info["session_id"]
        if session_info.get("model"):
            details["model"] = session_info["model"]
        if session_info.get("cost_usd"):
            details["cost_usd"] = session_info["cost_usd"]
        if session_info.get("cwd"):
            details["cwd"] = session_info["cwd"]

    # If we still don't have cwd, try to extract from the project directory slug.
    # The transcript lives at ~/.claude/projects/<slug>/<session_id>.jsonl
    # where <slug> is the cwd with / replaced by - and _ replaced by -.
    # This reverse mapping is lossy, so only use it as a fallback.
    if not details.get("cwd"):
        try:
            project_dir = transcript_path.parent
            if project_dir.parent.name == "projects":
                slug = project_dir.name
                # Reverse the slug: leading - becomes /, remaining - become /
                # This is lossy for paths with actual hyphens
                if slug.startswith("-"):
                    candidate_cwd = slug.replace("-", "/")
                    if Path(candidate_cwd).is_dir():
                        details["cwd"] = candidate_cwd
        except Exception:
            pass

    # Git info from cwd
    cwd = details.get("cwd")
    if cwd:
        details.update(_get_git_info(cwd))

    # MCP servers from Claude settings (global, not per-session)
    mcp = _get_mcp_servers_for_tool("claude")
    if mcp:
        details["mcp_servers"] = mcp

    # Tasks
    sid = details.get("session_id")
    tasks = _get_claude_tasks(sid)
    if tasks:
        details["tasks"] = tasks

    return details


def get_codex_details_from_file(rollout_path: Path) -> dict[str, Any]:
    """Extract model, session_id, cwd, git info from a Codex rollout file."""
    details: dict[str, Any] = {}
    details["transcript_path"] = str(rollout_path)

    try:
        with open(rollout_path, "r", encoding="utf-8") as f:
            first_line = f.readline().strip()
            if first_line:
                header = json.loads(first_line)
                payload = header.get("payload", {})
                if isinstance(payload, dict) and payload:
                    details["session_id"] = payload.get("id", "")
                    details["model"] = payload.get("model_provider", "")
                    cwd = payload.get("cwd", "")
                    if cwd:
                        details["cwd"] = cwd
                        details.update(_get_git_info(cwd))
                else:
                    details["session_id"] = header.get("session_id", "")
                    details["model"] = header.get("model", "")
    except Exception as e:
        logger.debug("Error reading Codex rollout header: %s", e)

    return details


def get_opencode_details_from_config() -> dict[str, Any]:
    """Extract basic OpenCode info from config files.

    Without a PID we cannot derive the HTTP API port, so we return
    whatever we can find from static config files.
    """
    details: dict[str, Any] = {"api_available": False}

    config_dir = Path.home() / ".config" / "opencode"
    if not config_dir.exists():
        return details

    # Try to read any config/state files
    try:
        config_path = config_dir / "config.json"
        if config_path.exists():
            with open(config_path, "r", encoding="utf-8") as f:
                config = json.load(f)
                if config.get("model"):
                    details["model"] = config["model"]
                if config.get("agent"):
                    details["agent_mode"] = config["agent"]
    except Exception as e:
        logger.debug("Error reading OpenCode config: %s", e)

    return details


# ===========================================================================
# Per-tool session discovery (file-based)
# ===========================================================================


def _get_claude_details_lightweight(transcript_path: Path) -> dict[str, Any]:
    """Fast detail extraction — reads file path + sessions-index.json only.

    Used for old/stopped sessions where full enrichment is wasteful.
    """
    details: dict[str, Any] = {}
    details["transcript_path"] = str(transcript_path)
    details["session_id"] = transcript_path.stem

    # Extract cwd from project directory slug (no subprocess)
    try:
        project_dir = transcript_path.parent
        if project_dir.parent.name == "projects":
            slug = project_dir.name
            if slug.startswith("-"):
                candidate_cwd = slug.replace("-", "/")
                if Path(candidate_cwd).is_dir():
                    details["cwd"] = candidate_cwd
    except Exception:
        pass

    # Read session title from sessions-index.json (lightweight — one JSON read per project)
    title = _get_claude_session_title(transcript_path.parent, transcript_path.stem)
    if title:
        details["terminal_name"] = title

    return details


def _discover_claude_sessions(
    enrich_threshold_s: float = ENRICHMENT_THRESHOLD_S,
) -> list[AgentSession]:
    """Discover Claude sessions by scanning transcript files.

    Scans ~/.claude/projects/ recursively for all .jsonl transcript files.
    Each transcript file represents a distinct session.

    Args:
        enrich_threshold_s: Sessions newer than this (in seconds) get full
            detail enrichment (git, model, cost, tasks). Older sessions get
            lightweight path-based extraction only. Default: 30 days.
            Pass ``float('inf')`` to enrich everything.
    """
    sessions: list[AgentSession] = []
    projects_dir = Path.home() / ".claude" / "projects"

    if not projects_dir.exists():
        return sessions

    now = time.time()

    try:
        # Find ALL .jsonl files recursively, but skip subagent transcripts
        # (subagents/ dirs contain child session transcripts, not top-level sessions)
        all_jsonl = [p for p in projects_dir.rglob("*.jsonl") if "subagents" not in p.parts]

        for transcript in all_jsonl:
            try:
                file_mtime = transcript.stat().st_mtime
            except OSError:
                continue

            # Full enrichment for recent sessions, lightweight for old ones
            age = now - file_mtime
            if age <= enrich_threshold_s:
                details = get_claude_details_from_transcript(transcript)
            else:
                details = _get_claude_details_lightweight(transcript)

            # Build session
            session = _build_session(
                tool_id="claude",
                details=details,
                transcript_path=transcript,
                file_mtime=file_mtime,
            )
            if session is not None:
                sessions.append(session)

    except Exception as e:
        logger.debug("Error discovering Claude sessions: %s", e)

    return sessions


OPENCODE_DB_PATH = Path.home() / ".local" / "share" / "opencode" / "opencode.db"


def _parse_opencode_part(data: dict) -> Optional["TranscriptEntry"]:
    """Parse an OpenCode part record into a TranscriptEntry."""
    from .schemas import TranscriptEntry

    part_type = data.get("type", "")
    timestamp = data.get("time", {}).get("start") or data.get("time", {}).get("created")
    if timestamp and timestamp > 1e12:
        timestamp = timestamp / 1000  # ms to seconds

    if part_type == "text":
        return TranscriptEntry(
            type="assistant_text",
            timestamp=timestamp,
            content=data.get("text", ""),
        )
    if part_type == "reasoning":
        return TranscriptEntry(
            type="thinking",
            timestamp=timestamp,
            content=data.get("text", ""),
        )
    if part_type == "tool":
        tool_name = data.get("tool", "")
        state = data.get("state", {})
        status = state.get("status", "")
        if status == "running":
            return TranscriptEntry(
                type="tool_call",
                timestamp=timestamp,
                content=str(state.get("input", {}).get("content", ""))[:300],
                tool_name=tool_name,
            )
        if status in ("completed", "error"):
            return TranscriptEntry(
                type="tool_result",
                timestamp=timestamp,
                content=str(state.get("output", ""))[:300],
                tool_name=tool_name,
                tool_success=status == "completed",
            )
    if part_type == "step-start":
        return TranscriptEntry(
            type="status_change",
            timestamp=timestamp,
            content="step_start",
        )

    return None


def get_opencode_sessions_from_db(
    db_path: Path = OPENCODE_DB_PATH,
) -> list[dict[str, Any]]:
    """Read all sessions from the OpenCode SQLite database.

    Returns a list of dicts with: id, title, directory, model,
    time_created, time_updated.
    """
    if not db_path.exists():
        return []

    import sqlite3

    sessions = []
    try:
        conn = sqlite3.connect(str(db_path), timeout=5)
        conn.row_factory = sqlite3.Row
        cursor = conn.execute(
            "SELECT s.id, s.title, s.directory, s.time_created, s.time_updated "
            "FROM session s ORDER BY s.time_updated DESC"
        )
        for row in cursor:
            ts_created = row["time_created"]
            ts_updated = row["time_updated"]
            # OpenCode timestamps are in milliseconds
            if ts_created and ts_created > 1e12:
                ts_created = ts_created / 1000
            if ts_updated and ts_updated > 1e12:
                ts_updated = ts_updated / 1000

            # Get model from the most recent assistant message
            model = None
            try:
                msg_cursor = conn.execute(
                    "SELECT data FROM message WHERE session_id = ? "
                    "ORDER BY time_created DESC LIMIT 1",
                    (row["id"],),
                )
                msg_row = msg_cursor.fetchone()
                if msg_row:
                    msg_data = json.loads(msg_row["data"])
                    model = msg_data.get("modelID")
            except Exception:
                pass

            sessions.append(
                {
                    "session_id": row["id"],
                    "title": row["title"],
                    "cwd": row["directory"],
                    "model": model,
                    "started_at": ts_created,
                    "last_activity": ts_updated,
                }
            )
        conn.close()
    except Exception as e:
        logger.debug("Error reading OpenCode DB: %s", e)

    return sessions


def watch_opencode_session(
    session_id: str,
    db_path: Path = OPENCODE_DB_PATH,
    poll_interval: float = 1.0,
    initial_entries: int = 20,
):
    """Yield new OpenCode transcript entries by polling the SQLite database.

    Same interface as watch_transcript but reads from OpenCode's DB.
    """
    from .schemas import TranscriptEntry

    if not db_path.exists():
        return

    import sqlite3

    conn = sqlite3.connect(str(db_path), timeout=5)
    try:
        conn.row_factory = sqlite3.Row

        # Yield initial history
        cursor = conn.execute(
            "SELECT data, time_created FROM part WHERE session_id = ? "
            "ORDER BY time_created DESC LIMIT ?",
            (session_id, initial_entries),
        )
        rows = list(cursor)
        rows.reverse()  # oldest first

        last_ts = 0
        for row in rows:
            try:
                data = json.loads(row["data"])
                entry = _parse_opencode_part(data)
                if entry:
                    yield entry
                    last_ts = row["time_created"]
            except Exception:
                pass

        # Poll for new entries
        while True:
            time.sleep(poll_interval)
            try:
                cursor = conn.execute(
                    "SELECT data, time_created FROM part WHERE session_id = ? "
                    "AND time_created > ? ORDER BY time_created",
                    (session_id, last_ts),
                )
                for row in cursor:
                    try:
                        data = json.loads(row["data"])
                        entry = _parse_opencode_part(data)
                        if entry:
                            yield entry
                            last_ts = row["time_created"]
                    except Exception:
                        pass
            except Exception:
                pass
    finally:
        conn.close()


def _discover_opencode_sessions() -> list[AgentSession]:
    """Discover OpenCode sessions from the SQLite database.

    Reads ``~/.local/share/opencode/opencode.db`` for session history.
    """
    db_sessions = get_opencode_sessions_from_db()
    if not db_sessions:
        return []

    now = time.time()
    sessions = []

    for s in db_sessions:
        last_activity = s.get("last_activity", 0)
        age = now - last_activity if last_activity else float("inf")

        if age > ACTIVITY_THRESHOLD_S:
            status = AgentStatus.STOPPED
        else:
            status = AgentStatus.IDLE

        session = AgentSession(
            session_id=s["session_id"],
            tool=AgentTool.CODEQ,
            pid=0,
            status=status,
            cwd=s.get("cwd"),
            external=True,
            model_name=s.get("model"),
            terminal_name=s.get("title") or None,
            started_at=s.get("started_at"),
            last_activity=last_activity,
        )
        sessions.append(session)

    return sessions


def _discover_codex_sessions() -> list[AgentSession]:
    """Discover Codex sessions by scanning rollout files.

    Scans ~/.codex/sessions/ for rollout-*.jsonl files.
    """
    sessions: list[AgentSession] = []
    codex_dir = Path.home() / ".codex" / "sessions"

    if not codex_dir.exists():
        return sessions

    try:
        rollout_files = sorted(
            codex_dir.rglob("rollout-*.jsonl"),
            key=lambda p: p.stat().st_mtime,
            reverse=True,
        )

        for rollout in rollout_files:
            try:
                file_mtime = rollout.stat().st_mtime
            except OSError:
                continue

            details = get_codex_details_from_file(rollout)

            session = _build_session(
                tool_id="codex",
                details=details,
                transcript_path=rollout,
                file_mtime=file_mtime,
            )
            if session is not None:
                sessions.append(session)

    except Exception as e:
        logger.debug("Error discovering Codex sessions: %s", e)

    return sessions


# ===========================================================================
# Session builder
# ===========================================================================


def _build_session(
    tool_id: str,
    details: dict[str, Any],
    transcript_path: Path,
    file_mtime: float,
) -> Optional[AgentSession]:
    """Build an AgentSession from extracted details and file metadata.

    Args:
        tool_id: The tool identifier ("claude", "codeq", "codex").
        details: Detail dict from the per-tool enrichment function.
        transcript_path: Path to the transcript/rollout file.
        file_mtime: The mtime of the transcript file.

    Returns:
        AgentSession, or None if we can't build a valid session.
    """
    now = time.time()
    age = now - file_mtime

    # Determine status: stale files mean stopped, otherwise use detailed detection
    if age > ACTIVITY_THRESHOLD_S:
        status = AgentStatus.STOPPED
    else:
        status = detect_agent_status(tool_id, details=details)

    # Build GitInfo if available
    git_info = None
    if details.get("git_branch") or details.get("github_repo"):
        git_info = GitInfo(
            branch=details.get("git_branch"),
            remote_url=details.get("github_repo"),
            is_worktree=details.get("git_worktree", False),
        )

    # Build task list
    tasks = []
    for t in details.get("tasks", []):
        tasks.append(
            AgentTask(
                id=t.get("id", ""),
                subject=t.get("subject", ""),
                status=t.get("status", "pending"),
                active_form=t.get("activeForm", ""),
            )
        )

    # Map tool_id to AgentTool enum
    try:
        tool = AgentTool(tool_id)
    except ValueError:
        tool = AgentTool.CLAUDE

    session_id = details.get("session_id", "")
    if not session_id:
        # Use the transcript filename stem as a fallback session_id
        session_id = transcript_path.stem

    return AgentSession(
        session_id=session_id,
        tool=tool,
        pid=0,  # File-based discovery doesn't know the PID
        status=status,
        cwd=details.get("cwd"),
        port=details.get("port"),
        external=True,
        model_name=details.get("model"),
        git=git_info,
        mcp_servers=details.get("mcp_servers", []),
        transcript_path=details.get("transcript_path", str(transcript_path)),
        cost_usd=details.get("cost_usd") or details.get("total_cost"),
        total_tokens=details.get("total_tokens") or details.get("tokens"),
        tasks=tasks,
        started_at=file_mtime,
        last_activity=file_mtime,
    )


# ===========================================================================
# Main discovery entry point
# ===========================================================================


def detect_sessions(enrich_all: bool = False) -> list[AgentSession]:
    """Discover agent sessions by scanning CLI tool files.

    Scans transcript/session files for Claude, OpenCode, and Codex.
    Sessions with activity within the last 30 minutes are marked active;
    older sessions are marked stopped.

    Args:
        enrich_all: If True, run full detail enrichment on every session
            regardless of age. Default is False (only last 30 days).

    Returns:
        List of discovered AgentSession objects.
    """
    threshold = float("inf") if enrich_all else ENRICHMENT_THRESHOLD_S

    sessions: list[AgentSession] = []
    sessions.extend(_discover_claude_sessions(enrich_threshold_s=threshold))
    sessions.extend(_discover_opencode_sessions())
    sessions.extend(_discover_codex_sessions())
    return sessions
